import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 11 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * Practice Tests 1–10.
 */

// ─────────────────────── PRACTICE TEST 11 · R&W M1 (27) ──────────────────────
const T11_RW_M1: SatQuestion[] = [
  { id: "t11rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The violinist's interpretation was praised as ______: she lingered over phrases that other performers rushed through, drawing out emotions the score only hinted at.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["nuanced", "careless", "hurried", "tuneless"], correct: 0, explanation: "The blank describes an interpretation that was praised, and the colon explains why: she lingered over phrases to draw out emotions the score only hinted at. Sensitivity to subtle, implied feeling is exactly what \"nuanced\" means, so it is correct. \"Careless\" (B) is negative and contradicts the praise. \"Hurried\" (C) directly contradicts \"lingered\" and \"rushed through,\" which describe the opposite of what she did. \"Tuneless\" (D) would insult a praised musician and has nothing to do with subtle emotion." },
  { id: "t11rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of advisors ______ scheduled to release its recommendations next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "Subject-verb agreement rule: the verb agrees with the grammatical subject, not with a noun inside an intervening prepositional phrase. The subject here is the singular collective noun \"committee\"; \"of advisors\" is a prepositional phrase that does not change the subject's number, so the singular \"is\" (A) is correct. \"Are\" (B) and \"were\" (D) are plural and wrongly agree with the nearby \"advisors.\" \"Have been\" (C) is also plural and additionally shifts to a perfect form the sentence does not need." },
  { id: "t11rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Cleaner shrimp set up stations on coral reefs where larger fish queue to have parasites picked from their gills and mouths; the shrimp gain a meal, and the fish leave free of pests.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The shrimp and the fish each benefit from the cleaning exchange.", "The shrimp harm the fish by feeding on them.", "The fish avoid the shrimp's stations entirely.", "The shrimp gain nothing from the interaction."], correct: 0, explanation: "The text says the shrimp \"gain a meal\" and the fish \"leave free of pests,\" so each side gains from the exchange; choice A captures this mutual benefit and is correct. Choice B (\"harm... by feeding on them\") reverses the relationship — the shrimp eat parasites, not the fish. Choice C (\"avoid the shrimp's stations entirely\") contradicts \"larger fish queue.\" Choice D (\"gain nothing\") ignores the explicitly stated meal." },
  { id: "t11rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The harvest had been ruined by drought. ______, the village rationed its grain through the winter.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "Otherwise"], correct: 1, explanation: "The first sentence states a cause (the harvest was ruined by drought) and the second states its direct effect (the village rationed grain). A result transition is needed, and \"Consequently\" (B) signals exactly that, so it is correct. \"Nevertheless\" (A) and \"However\" (C) signal contrast, but rationing does not oppose the ruined harvest — it follows from it. \"Otherwise\" (D) means 'if not,' introducing an alternative, which does not fit a straightforward consequence." },
  { id: "t11rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The expedition packed three essentials ______ rope, a compass, and a week's supply of water.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials, ", "essentials: ", "essentials; ", "essentials "], correct: 1, explanation: "Punctuation rule: a colon follows a complete clause to introduce a list or explanation. \"The expedition packed three essentials\" is a complete clause, and what follows is the list of those essentials, so the colon (B) is correct. The comma (A) is too weak to formally introduce the list after a full clause. The semicolon (C) must join two independent clauses, but the list \"rope, a compass...\" is not an independent clause. No punctuation (D) runs the clause and list together without the needed signal." },
  { id: "t11rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her lecture notes were remarkably ______, condensing an hour of material into a single, clearly labeled page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["concise", "rambling", "illegible", "lengthy"], correct: 0, explanation: "The blank is defined by the detail that follows: the notes condense an hour of material into a single, clearly labeled page. Saying much in little space is exactly \"concise\" (A), so it is correct. \"Rambling\" (B) and \"lengthy\" (D) describe long-winded writing, the opposite of condensing into one page. \"Illegible\" (C) means unreadable, which contradicts \"clearly labeled.\"" },
  { id: "t11rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is awarded only to applicants who major in engineering and who have completed at least two semesters of calculus; all other applicants are ineligible.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A biology major cannot receive the scholarship.", "Any applicant who applies will receive it.", "Calculus is not required for the award.", "Engineering majors are automatically excluded."], correct: 0, explanation: "The text sets two requirements — an engineering major and two semesters of calculus — and says all other applicants are ineligible. A biology major fails the engineering requirement, so choice A (the biology major cannot receive it) is directly supported. Choice B (\"any applicant... will receive it\") ignores the stated conditions. Choice C (\"calculus is not required\") contradicts the explicit calculus requirement. Choice D (\"engineering majors are automatically excluded\") reverses the rule — engineering majors are precisely the ones eligible." },
  { id: "t11rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum restored its oldest gallery. ______, it digitized the entire collection so visitors could browse the artifacts online.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Instead", "Otherwise"], correct: 1, explanation: "The first sentence reports one accomplishment (restoring a gallery) and the second reports a further, similar accomplishment (digitizing the collection). These are two things the museum did, so the additive transition \"In addition\" (B) is correct. \"However\" (A) signals contrast, but digitizing does not oppose restoring. \"Instead\" (C) implies the second replaced the first, but both happened. \"Otherwise\" (D) means 'if not,' a consequence that does not fit." },
  { id: "t11rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The novel's villain was deliberately ______, charming readers even as he plotted betrayals they could not forgive.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["complicated", "simple", "forgettable", "transparent"], correct: 0, explanation: "The blank must fit a villain who charms readers even while plotting betrayals — a mix of appealing and repellent traits. \"Complicated\" (A) captures that contradictory blend and is correct. \"Simple\" (B) and \"transparent\" (D) both deny the mixture, implying he is easy to read, which the description contradicts. \"Forgettable\" (C) contradicts a character whose betrayals readers \"could not forgive,\" a strong, memorable impression." },
  { id: "t11rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Arctic foxes grow a thick white coat in winter that hides them against the snow and a thinner brown coat in summer that matches the bare tundra.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The fox's coat changes seasonally to keep it camouflaged.", "The fox is always white year-round.", "The fox's coat offers no camouflage at all.", "The fox loses its fur entirely in summer."], correct: 0, explanation: "The text describes a white winter coat that hides the fox against snow and a brown summer coat that matches the bare tundra, so the coat changes seasonally to keep the fox camouflaged; choice A is correct. Choice B (\"always white year-round\") ignores the brown summer coat. Choice C (\"no camouflage at all\") contradicts \"hides them.\" Choice D (\"loses its fur entirely in summer\") misreads \"a thinner brown coat\" — the fox still has a coat, just a thinner one." },
  { id: "t11rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the coach nor the players ______ satisfied with the referee's final call.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "is", "were", "has been"], correct: 2, explanation: "Agreement rule for \"neither...nor\": the verb agrees with the subject nearer to it. The nearer subject is \"players,\" which is plural, so the plural \"were\" (C) is correct. \"Was\" (A), \"is\" (B), and \"has been\" (D) are all singular and would agree only with the farther subject, \"coach.\" Additionally, \"is\" (B) wrongly shifts to present tense in a past-tense sentence about the referee's final call." },
  { id: "t11rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The early electric cars had a very limited range. ______, they paved the way for the long-range models that dominate today's market.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "The first sentence names a drawback (limited range) and the second names a positive outcome that happened despite it (they paved the way for long-range models). This concessive contrast is signaled by \"Still\" (A), so it is correct. \"For instance\" (B) introduces an example, but the second sentence is not an example of limited range. \"Therefore\" (C) signals a result, yet success was not caused by the limitation. \"In short\" (D) signals a summary, but no restatement follows." },
  { id: "t11rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A clinic recorded average wait times of 42 minutes in the morning, 28 minutes at midday, and 51 minutes in the evening.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The evening had the longest average wait time.", "The midday had the longest average wait time.", "The morning wait exceeded the evening wait.", "All three periods had identical wait times."], correct: 0, explanation: "Compare the three averages: morning 42, midday 28, evening 51. The largest is 51 minutes in the evening, so choice A is correct. Choice B (midday longest) names 28, the smallest. Choice C (\"morning exceeded the evening\") compares 42 to 51 backwards — 42 is less than 51. Choice D (\"identical\") ignores that the three numbers differ." },
  { id: "t11rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive holds letters ______ were written by soldiers stationed overseas during the war.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and they"], correct: 0, explanation: "A relative pronoun is needed to introduce the clause modifying the noun \"letters.\" \"That\" (A) is the correct relative pronoun for a defining clause about things. \"What\" (B) cannot introduce a relative clause attached to a preceding noun. \"Where\" (C) introduces clauses about places, not about letters. \"And they\" (D) is not a relative pronoun; with no preceding comma it creates a run-on and leaves \"letters\" without its modifying clause." },
  { id: "t11rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Hiking up the steep trail, ______ the thin mountain air left the climbers short of breath.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["hiking up the steep trail, the thin mountain air left the climbers short of breath", "the climbers grew short of breath as they hiked up the steep trail in the thin mountain air", "the thin air, hiking up the steep trail, left them breathless", "short of breath, the trail steepened for the climbers"], correct: 1, explanation: "Modifier rule: an introductory participial phrase like \"Hiking up the steep trail\" must be followed by the noun actually performing that action. Only the climbers can hike, so choice B, which makes \"the climbers\" the subject right after the action, is correct (it also smoothly rewrites the sentence). Choice A leaves \"the thin mountain air\" as the thing hiking — a dangling modifier. Choice C illogically makes \"the thin air\" do the hiking. Choice D makes \"the trail\" short of breath and steepening on its own, which is both dangling and illogical." },
  { id: "t11rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist argues that raising the minimum wage modestly tends to increase consumer spending, because lower-income workers spend nearly all of any extra income.", prompt: "Which finding, if true, would most strengthen the economist's claim?", type: "mcq", choices: ["After a modest wage increase, retail sales rose most in lower-income neighborhoods.", "Wealthy households saved most of their income.", "Minimum-wage workers make up a small share of the population.", "Consumer spending fell after the wage increase."], correct: 0, explanation: "The economist's claim is that a modest minimum-wage rise boosts consumer spending because low-income workers spend nearly all extra income. Choice A — retail sales rising most in lower-income neighborhoods after a wage increase — shows exactly that spending response, so it strengthens the claim. Choice B describes wealthy households' saving, which is irrelevant to low-wage spending. Choice C (workers are a small share) bears on scale, not on whether they spend, and if anything weakens the claim. Choice D (spending fell) directly contradicts the claim." },
  { id: "t11rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with her producers, ______ planning to announce the film's release date soon.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "Agreement rule: a phrase beginning with \"together with\" (like \"with,\" \"along with,\" \"as well as\") is parenthetical and does not change the number of the subject. The subject is the singular \"director,\" so the singular \"is\" (A) is correct. \"Are\" (B), \"were\" (C), and \"have been\" (D) are plural and wrongly agree with \"producers\" inside the set-off phrase; \"were\" and \"have been\" also disrupt the sentence's present-tense plan (\"to announce... soon\")." },
  { id: "t11rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to underscore that two separate labs reached the same surprising result. ______, both teams measured the reaction rate doubling at the same temperature.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "The writer wants to underscore that two separate labs reached the same surprising result, so the transition should emphasize how striking the agreement is. \"Remarkably\" (B) does exactly that and is correct. \"By contrast\" (A) and \"However\" (C) signal disagreement, but the two labs agreed, not differed. \"Otherwise\" (D) means 'if not,' introducing an alternative outcome that does not fit the matching results." },
  { id: "t11rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The essayist's tone is deceptively ______: beneath the breezy anecdotes lies a sharp critique of the institutions she pretends merely to describe.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["casual", "hostile", "formal", "obvious"], correct: 0, explanation: "The word \"deceptively\" tells us the surface tone hides something, and the colon explains that beneath the breezy anecdotes lies a sharp critique. A tone that seems light but conceals depth is \"deceptively casual\" (A), so it is correct. \"Hostile\" (B) would openly show the critique rather than disguise it. \"Formal\" (C) contradicts the \"breezy anecdotes.\" \"Obvious\" (D) contradicts \"deceptively,\" since the critique is hidden, not plain to see." },
  { id: "t11rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The grant supports only projects that involve at least two partner schools and that will be completed within three years; projects that miss either condition are rejected.", prompt: "Which project clearly qualifies for the grant?", type: "mcq", choices: ["A two-school project scheduled to finish in two years.", "A single-school project scheduled to finish in two years.", "A two-school project scheduled to finish in five years.", "A project involving no schools at all."], correct: 0, explanation: "The grant requires both conditions: at least two partner schools AND completion within three years; missing either causes rejection. Choice A (two schools, finishing in two years) meets both, so it qualifies. Choice B (single school) fails the two-school requirement. Choice C (finishing in five years) fails the three-year deadline. Choice D (no schools at all) fails the school requirement." },
  { id: "t11rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the bridge's cables ______ they repainted its rusted railings.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["cables, and then", "cables and, then", "cables then", "cables, then"], correct: 0, explanation: "Two independent clauses (\"The crew repaired the bridge's cables\" and \"they repainted its rusted railings\") must be joined by a comma plus a coordinating conjunction. \"Cables, and then\" (A) does this correctly. \"Cables, then\" (D) joins the clauses with only a comma — a comma splice, since \"then\" is an adverb, not a conjunction. \"Cables then\" (C) fuses the clauses with no punctuation (a run-on). \"Cables and, then\" (B) keeps the \"and\" but misplaces the comma after it." },
  { id: "t11rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although the professor was famous for his ______ lectures, he answered students' questions with unexpected patience after class.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["intimidating", "soothing", "tentative", "welcoming"], correct: 0, explanation: "\"Although\" sets up a contrast with \"answered students' questions with unexpected patience,\" so the blank must describe lectures that seem to clash with patience. \"Intimidating\" (A) provides that contrast and is correct. \"Soothing\" (B) and \"welcoming\" (D) would match, not contrast with, patient kindness, breaking the \"Although\" logic. \"Tentative\" (C) means hesitant, which does not contrast with patience and ill-fits a professor famous for his lectures." },
  { id: "t11rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A geographer notes that coastal cities with deep natural harbors grew into major trading hubs faster than inland cities, crediting the ease of shipping goods by sea.", prompt: "Which choice best describes the geographer's explanation?", type: "mcq", choices: ["Deep harbors eased sea shipping, speeding the cities' growth.", "Inland cities had better access to shipping.", "Harbors slowed the growth of coastal cities.", "Location had no effect on a city's growth."], correct: 0, explanation: "The geographer says coastal cities with deep harbors grew into hubs faster than inland cities and credits the ease of shipping goods by sea. Choice A restates this cause and effect and is correct. Choice B (\"inland cities had better access\") reverses the advantage. Choice C (\"harbors slowed... growth\") contradicts \"faster.\" Choice D (\"location had no effect\") denies the very cause the geographer names." },
  { id: "t11rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The team delayed the launch ______ the final test had revealed a flaw in the cooling system.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["launch because", "launch, because", "launch; because", "launch: because"], correct: 0, explanation: "Punctuation rule: when a dependent clause beginning with \"because\" follows the main clause and is essential to its meaning, no punctuation separates them. So \"launch because\" (A) is correct. The comma in (B) wrongly breaks the tight main-clause/because-clause link. The semicolon in (C) must join two independent clauses, but \"because the final test...\" is dependent, not independent. The colon in (D) introduces a list or explanation set off after a complete statement, which does not fit here." },
  { id: "t11rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory switched to solar power. ______, its monthly electricity bills dropped by nearly half.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The first sentence states a cause (switching to solar power) and the second states its direct effect (bills dropped by nearly half), so a result transition is needed; \"As a result\" (A) signals exactly that and is correct. \"Nevertheless\" (B) signals contrast, but the lower bills follow from the switch rather than oppose it. \"For example\" (C) introduces an illustration, yet the dropped bills are an outcome, not an example of switching. \"On the other hand\" (D) signals a contrasting viewpoint, which does not fit a straightforward consequence." },
  { id: "t11rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach offered ______ feedback, pointing out exactly which step in the routine each gymnast needed to fix.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "vague", "general", "misleading"], correct: 0, explanation: "The blank is defined by the detail that follows: the coach points out exactly which step each gymnast needs to fix. Feedback that targets a precise, named detail is \"specific\" (A), so it is correct. \"Vague\" (B) and \"general\" (C) both describe imprecise feedback, the opposite of pinpointing an exact step. \"Misleading\" (D) means deceptive or inaccurate, which contradicts the helpful, corrective coaching the sentence describes." },
  { id: "t11rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Researchers found that removing an invasive crab from tidal pools allowed native snail populations to rebound, which in turn let the seaweed the snails graze upon thin out, restoring balance to the pools.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Removing the invasive crab set off a chain of effects that rebalanced the tidal pools.", "The invasive crab directly planted the seaweed.", "Snail populations fell after the crab was removed.", "The seaweed grew thicker once the crab left."], correct: 0, explanation: "Removing the crab let snails rebound, which thinned the seaweed and restored balance — a chain of effects, so choice A is correct. Choice B (\"directly planted the seaweed\") invents an action the text never mentions; the crab's role was suppressing snails, not planting. Choice C (\"snail populations fell\") reverses the stated rebound. Choice D (\"seaweed grew thicker\") reverses the explicit statement that the seaweed thinned out." },
];

// ─────────────────────── PRACTICE TEST 11 · R&W M2 easy (27) ─────────────────
const T11_RW_M2E: SatQuestion[] = [
  { id: "t11rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was so ______ that she could barely lift it onto her shoulders.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "empty", "soft", "quiet"], correct: 0, explanation: "The blank describes the backpack, and the result clause explains it: she could barely lift it. A backpack that is hard to lift is \"heavy\" (A), so it is correct. \"Empty\" (B) would make it light and easy to lift, the opposite. \"Soft\" (C) describes texture, not weight, and would not strain her. \"Quiet\" (D) describes sound and has nothing to do with lifting." },
  { id: "t11rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three children ______ playing in the park after school.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Subject-verb agreement rule: the verb must match the number of its subject. The subject \"three children\" is plural, so the plural \"are\" (B) is correct. \"Is\" (A) and \"was\" (C) are singular and cannot agree with a plural subject; \"was\" also wrongly shifts to past tense. \"Am\" (D) is the first-person singular form, used only with \"I.\"" },
  { id: "t11rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bees carry pollen from flower to flower as they gather nectar, helping the plants make seeds.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees help plants reproduce by moving pollen between flowers.", "Bees destroy the flowers they visit.", "Bees never touch flowers.", "Plants make seeds without any help."], correct: 0, explanation: "The text says bees carry pollen between flowers, helping the plants make seeds, so they aid reproduction; choice A is correct. Choice B (\"destroy the flowers\") contradicts the helpful visiting the text describes. Choice C (\"never touch flowers\") contradicts \"carry pollen from flower to flower.\" Choice D (\"without any help\") ignores the bees' stated role in moving the pollen." },
  { id: "t11rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The road was covered in ice. ______, the driver slowed down to stay safe.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The first sentence states a cause (the road was icy) and the second states its effect (the driver slowed to stay safe), so a result transition is needed; \"So\" (B) signals exactly that and is correct. \"For example\" (A) introduces an illustration, but slowing is an outcome, not an example. \"However\" (C) signals contrast, yet slowing follows from the ice rather than opposing it. \"Meanwhile\" (D) signals simultaneous events, which does not fit a cause-and-effect link." },
  { id: "t11rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at our grandmother's house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "Verb-tense rule: a past-time marker like \"Last night\" requires the past tense, so \"ate\" (C) is correct. \"Eat\" (A) and \"eats\" (B) are present-tense forms that clash with the past-time signal; \"eats\" is also singular and would not agree with \"we.\" \"Eating\" (D) is a participle that cannot serve as the main verb without a helping verb such as \"were.\"" },
  { id: "t11rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puppy was very ______, running in circles and chasing its tail all afternoon.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["energetic", "sleepy", "silent", "still"], correct: 0, explanation: "The blank is defined by the detail that follows: running in circles and chasing its tail all afternoon. That nonstop activity is \"energetic\" (A), so it is correct. \"Sleepy\" (B) and \"still\" (D) describe the opposite of constant motion. \"Silent\" (C) describes sound, not the activity the sentence describes." },
  { id: "t11rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives you exercise, and reduces traffic on busy roads.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is always dangerous.", "Walking to school only saves money.", "Driving to school is better in every way."], correct: 0, explanation: "The text lists three advantages of walking to school — saving money, exercise, and less traffic — so choice A (\"has several benefits\") captures the main idea. Choice B (\"always dangerous\") contradicts the wholly positive list. Choice C (\"only saves money\") names just one of the three benefits and ignores the rest. Choice D (\"driving is better in every way\") contradicts the text's praise of walking." },
  { id: "t11rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She read for ______ hour before falling asleep.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Article rule: use \"an\" before a word that begins with a vowel sound. \"Hour\" has a silent h and opens with a vowel sound, so \"an\" (B) is correct. \"A\" (A) is used only before consonant sounds, so it misfits the vowel sound of \"hour.\" \"The only\" (C) and \"some\" (D) are not indefinite articles and change the sentence's meaning." },
  { id: "t11rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The directions were so ______ that everyone finished the project without asking for help.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "secret", "wrong"], correct: 0, explanation: "The result clause explains the blank: everyone finished the project without asking for help. Directions that need no clarification are \"clear\" (A), so it is correct. \"Confusing\" (B) and \"wrong\" (D) would prompt people to ask for help, the opposite of the stated result. \"Secret\" (C) does not describe how easy directions are to follow." },
  { id: "t11rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and I ______ visiting the aquarium tomorrow.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Agreement rule: a compound subject joined by \"and\" is plural and takes a plural verb. \"My sister and I\" is plural, so \"are\" (B) is correct. \"Is\" (A) and \"was\" (C) are singular and cannot agree with the two-part subject; \"was\" also wrongly shifts to past tense for an event happening \"tomorrow.\" \"Am\" (D) is the singular form used only with \"I\" alone." },
  { id: "t11rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Polar bears have a thick layer of fat under their skin that keeps them warm in freezing water.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["A layer of fat helps polar bears stay warm in cold water.", "Polar bears cannot survive in cold water.", "Polar bears have no fat at all.", "Polar bears avoid the water completely."], correct: 0, explanation: "The text says a thick layer of fat keeps polar bears warm in freezing water, so choice A is correct. Choice B (\"cannot survive in cold water\") contradicts the stated warmth the fat provides. Choice C (\"have no fat at all\") contradicts the explicit \"thick layer of fat.\" Choice D (\"avoid the water completely\") is unsupported and conflicts with the bears' described cold-water tolerance." },
  { id: "t11rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, the family lit candles to see.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The first sentence states a cause (the power went out) and the second states its effect (the family lit candles to see), so a result transition is needed; \"As a result\" (B) is correct. \"However\" (A) and \"Instead\" (D) signal contrast, but lighting candles follows from the outage rather than opposing it. \"For example\" (C) introduces an illustration, yet the candles are an outcome, not an example of losing power." },
  { id: "t11rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last week the class ______ a trip to the science center.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["take", "takes", "took", "taking"], correct: 2, explanation: "Verb-tense rule: the past-time marker \"Last week\" requires the past tense, so \"took\" (C) is correct. \"Take\" (A) and \"takes\" (B) are present-tense forms that clash with the past-time signal; \"takes\" is also singular. \"Taking\" (D) is a participle that cannot serve as the main verb without a helping verb." },
  { id: "t11rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After missing lunch, the hikers were ______ and stopped to share their snacks.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["hungry", "full", "thrilled", "calm"], correct: 0, explanation: "The sentence gives a cause (the hikers missed lunch) and an action (they stopped to share snacks), so the blank must explain wanting food: they were \"hungry\" (A), which is correct. \"Full\" (B) is the opposite and would give no reason to eat. \"Thrilled\" (C) and \"calm\" (D) describe moods that do not follow from a missed meal or explain stopping for food." },
  { id: "t11rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from 8 a.m. to 8 p.m. every day except Mondays, when it is closed for cleaning.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot swim at the pool on Mondays.", "The pool is open at midnight.", "The pool never closes.", "The pool is closed on weekends."], correct: 0, explanation: "The text says the pool is closed Mondays for cleaning, so choice A (\"cannot swim on Mondays\") is directly supported. Choice B (\"open at midnight\") contradicts the stated 8 a.m. to 8 p.m. hours. Choice C (\"never closes\") contradicts both the daily hours and the Monday closure. Choice D (\"closed on weekends\") names the wrong days — the closure is Mondays, not weekends." },
  { id: "t11rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after eating.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "Possessive rule: \"its\" is the singular possessive pronoun, with no apostrophe, and it matches the singular noun \"cat,\" so (A) is correct. \"It's\" (B) is the contraction for \"it is\" and makes no sense (\"it is paws\"). \"Their\" (C) and \"they're\" (D) are plural and cannot refer back to a single cat; \"they're\" also means \"they are.\"" },
  { id: "t11rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Many animals sleep during the day. ______, owls rest while the sun is up and hunt at night.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "The first sentence makes a general claim (many animals sleep during the day) and the second gives a specific case (owls rest while the sun is up), so an illustration transition is needed; \"For example\" (A) is correct. \"However\" (B) and \"Instead\" (C) signal contrast, but owls support the claim rather than opposing it. \"Otherwise\" (D) signals a consequence, which does not fit an example." },
  { id: "t11rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The hallway was so ______ that we had to whisper to hear each other.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["noisy", "empty", "narrow", "bright"], correct: 0, explanation: "The result clause defines the blank: they had to whisper to hear each other. A space loud enough to force whispering is \"noisy\" (A), so it is correct. \"Empty\" (B) and \"narrow\" (C) describe the hallway's space, not its sound, and neither would force whispering. \"Bright\" (D) describes light, which is unrelated to being heard." },
  { id: "t11rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The keys ______ hanging on the hook by the door.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Subject-verb agreement rule: the verb matches the number of its subject. The subject \"keys\" is plural, so the plural \"are\" (B) is correct. \"Is\" (A) and \"was\" (C) are singular and cannot agree with the plural \"keys\"; \"was\" also shifts to past tense. \"Am\" (D) is the singular form used only with \"I.\"" },
  { id: "t11rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Ants work together to carry food much larger than themselves back to their nest.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Ants cooperate to move large pieces of food.", "Ants never share food.", "Ants cannot lift anything.", "Ants live alone."], correct: 0, explanation: "The text says ants work together to carry food larger than themselves, so choice A (\"cooperate to move large pieces of food\") is correct. Choice B (\"never share food\") contradicts \"work together.\" Choice C (\"cannot lift anything\") contradicts \"carry food much larger than themselves.\" Choice D (\"live alone\") contradicts the cooperative behavior the text describes." },
  { id: "t11rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to picnic in the park. ______, it began to rain before we arrived.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The first sentence states a plan (to picnic) and the second states an obstacle that frustrates it (it began to rain), so a contrast transition is needed; \"However\" (A) is correct. \"Therefore\" (B) signals a result, but the rain opposes the plan rather than following from it. \"For example\" (C) introduces an illustration, and \"Similarly\" (D) signals likeness, neither of which fits the reversal." },
  { id: "t11rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month the band ______ to perform at the city festival.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "Agreement and tense: the singular collective noun \"band\" takes the singular verb \"plans\" (B), and the present tense suits a scheduled future event (\"next month\"). \"Plan\" (A) is the plural form and does not agree with singular \"band.\" \"Planned\" (C) is past tense and clashes with the future \"next month.\" \"Planning\" (D) is a participle that cannot serve as the main verb without a helping verb." },
  { id: "t11rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The soup needed more flavor, so the cook added salt to make it less ______.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["bland", "spicy", "hot", "thick"], correct: 0, explanation: "The sentence says the soup needed more flavor and the cook added salt to make it less ______, so the blank must name a lack of flavor: \"bland\" (A) is correct. \"Spicy\" (B) and \"hot\" (C) describe food that already has strong flavor, the opposite of what salt would fix. \"Thick\" (D) describes texture, not flavor, and salt does not change thickness." },
  { id: "t11rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Drinking enough water helps your body stay cool, keeps your skin healthy, and gives you energy.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Drinking water benefits the body in several ways.", "Drinking water is harmful.", "Water only cools the body.", "The body needs no water."], correct: 0, explanation: "The text lists three benefits of drinking water — staying cool, healthy skin, and energy — so choice A (\"benefits the body in several ways\") is the main idea. Choice B (\"is harmful\") contradicts the wholly positive list. Choice C (\"only cools the body\") names just one of the three benefits. Choice D (\"needs no water\") contradicts the text's point that water helps the body." },
  { id: "t11rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He carried ______ apple in his lunchbox every day.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Article rule: use \"an\" before a word beginning with a vowel sound. \"Apple\" opens with a vowel sound, so \"an\" (B) is correct. \"A\" (A) is used only before consonant sounds and misfits \"apple.\" \"The only\" (C) and \"some\" (D) are not indefinite articles and change the meaning of the sentence." },
  { id: "t11rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The bakery's bread is fresh and tasty. ______, it is sold at a very low price.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "The first sentence gives one good quality (the bread is fresh and tasty) and the second adds another (it is cheap), so an additive transition is needed; \"In addition\" (A) is correct. \"However\" (B) and \"Instead\" (C) signal contrast, but a low price reinforces rather than opposes the praise. \"Otherwise\" (D) signals a consequence, which does not fit two stacked positives." },
  { id: "t11rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "asleep", "angry"], correct: 0, explanation: "The blank describes the audience's reaction to the magician making a rabbit disappear, a surprising feat, so they were \"amazed\" (A); this is correct. \"Bored\" (B) and \"asleep\" (C) suggest no reaction at all, which contradicts a striking trick. \"Angry\" (D) is a negative response that does not fit a delightful illusion." },
];

// ─────────────────────── PRACTICE TEST 11 · R&W M2 hard (27) ─────────────────
const T11_RW_M2H: SatQuestion[] = [
  { id: "t11rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The committee's statement was carefully ______: it expressed sympathy for the protesters while committing the board to no actual change in policy.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["noncommittal", "decisive", "candid", "reckless"], correct: 0, explanation: "The colon defines the blank: the statement \"expressed sympathy... while committing the board to no actual change.\" A statement that voices feeling but pledges nothing is \"noncommittal\" (A), so it is correct. \"Decisive\" (B) means making a firm choice, the opposite of committing to no change. \"Candid\" (C) means frank and open, but a carefully hedged statement is guarded, not open. \"Reckless\" (D) means careless, which contradicts \"carefully.\"" },
  { id: "t11rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The article first surveys a wide range of failed startups, then narrows in its closing section to a single shared error: spending on growth before securing revenue.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from many examples to one unifying conclusion.", "It opens with a conclusion it never supports.", "It lists definitions without any examples.", "It repeats a single startup's story throughout."], correct: 0, explanation: "The text says the article \"first surveys a wide range of failed startups, then narrows... to a single shared error,\" moving from many examples to one unifying conclusion; choice A captures this structure and is correct. Choice B (\"opens with a conclusion it never supports\") reverses the order — the conclusion comes last and is supported by the survey. Choice C (\"lists definitions without any examples\") ignores the \"wide range of failed startups,\" which are examples. Choice D (\"repeats a single startup's story throughout\") contradicts the \"wide range\" of many startups." },
  { id: "t11rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A solar panel produced 98% of its rated output after 1 year, 95% after 5 years, and 80% after 20 years.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Output declined more steeply between years 5 and 20 than before.", "Output rose as the years passed.", "Output stayed perfectly constant.", "The panel produced nothing after 5 years."], correct: 0, explanation: "The data show 98% at year 1, 95% at year 5, then 80% at year 20: only 3 points lost across the first interval but 15 points lost across the later one, a steeper decline between years 5 and 20; choice A is correct. Choice B (\"output rose\") contradicts the steadily falling percentages. Choice C (\"stayed perfectly constant\") ignores that the numbers change. Choice D (\"produced nothing after 5 years\") contradicts the 80% still produced at year 20." },
  { id: "t11rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The new dam would generate clean electricity for the region. ______, it would flood several villages that have stood for centuries.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "The first sentence names a benefit (clean electricity) and the second names a serious drawback (flooding centuries-old villages); this opposition calls for the contrast transition \"However\" (B), which is correct. \"Therefore\" (A) and \"Accordingly\" (D) signal a result, but flooding villages is not an outcome the benefit produces. \"Likewise\" (C) signals similarity, yet the two effects are opposites, not alike." },
  { id: "t11rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write reports, and ______ their findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure rule: items in a series must share the same grammatical form. The first two items are infinitives, \"to analyze\" and \"to write,\" so the third must also be an infinitive, \"to present\" (A). \"Presenting\" (B) is a gerund, breaking the infinitive series. \"Present\" (C) is a bare verb with no \"to,\" inconsistent with the other items. \"Presented\" (D) is a past participle, which neither matches the form nor fits the present-tense list." },
  { id: "t11rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ the author's youth, dwelling on her cruelties as honestly as on her kindnesses.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "recount", "forget"], correct: 0, explanation: "The memoir \"dwells on her cruelties as honestly as on her kindnesses,\" so it refuses to idealize or sugarcoat the past; \"romanticize\" (A) names exactly what it refuses to do and is correct. \"Condemn\" (B) means to denounce harshly — refusing to condemn would mean going easy on her, the opposite of the honest, unflinching treatment described. \"Recount\" (C) means simply to narrate, but the memoir does recount her youth, so it would not \"refuse\" to. \"Forget\" (D) likewise contradicts a memoir that dwells in detail on her past." },
  { id: "t11rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats the city's founding as the work of a single visionary leader, recent scholarship recasts it as the slow product of many anonymous settlers.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older single-founder account with a newer collective one.", "To prove the city had one founder.", "To summarize only the traditional account.", "To argue the city was never founded."], correct: 0, explanation: "The \"Where the traditional account... recent scholarship recasts it...\" structure sets an older single-founder view against a newer collective one, so the purpose is to contrast them; choice A is correct. Choice B (\"prove the city had one founder\") states only the old view as fact, ignoring that the text questions it. Choice C (\"summarize only the traditional account\") omits the recent scholarship the text foregrounds. Choice D (\"argue the city was never founded\") misreads the passage, which discusses how it was founded, not whether." },
  { id: "t11rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The day shift met every deadline without complaint ______ the night shift fell behind on the same workload.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["complaint, the", "complaint; the", "complaint the", "complaint: the"], correct: 1, explanation: "Punctuation rule: two independent clauses may be joined by a semicolon. \"The day shift met every deadline\" and \"the night shift fell behind\" are both complete clauses, so the semicolon (B) is correct. A comma alone (A) creates a comma splice between two independent clauses. No punctuation (C) fuses them into a run-on. A colon (D) must follow a complete clause to introduce an explanation or list, but here the second clause is a contrasting statement, not an explanation of the first." },
  { id: "t11rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the report's prose bristles with technical terms that send even specialists reaching for a glossary.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["accessible", "dense", "specialized", "technical"], correct: 0, explanation: "\"Far from being ______\" signals that the blank is the OPPOSITE of how the prose actually reads, and the prose \"bristles with technical terms that send even specialists reaching for a glossary\" — i.e., it is hard to follow. Its opposite is \"accessible\" (A), so A is correct. \"Dense\" (B), \"specialized\" (C), and \"technical\" (D) all describe the difficult prose itself; placed after \"far from being,\" each would wrongly say the prose is far from difficult, contradicting the glossary detail." },
  { id: "t11rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters insist the new curfew lowered crime. Yet police reports show that offenses simply shifted to the hours just before the curfew took effect.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It offers evidence that complicates the supporters' claim.", "It restates the supporters' claim word for word.", "It confirms that crime fell overall.", "It proposes a stricter curfew."], correct: 0, explanation: "The first sentence gives the supporters' claim (the curfew lowered crime); the second, signaled by \"Yet,\" reports that offenses \"simply shifted\" to earlier hours rather than disappearing — evidence that complicates the claim, so choice A is correct. Choice B (\"restates the claim word for word\") is wrong because the second sentence challenges, not repeats, the claim. Choice C (\"confirms that crime fell overall\") contradicts \"shifted,\" which implies crime moved, not dropped. Choice D (\"proposes a stricter curfew\") adds a recommendation the sentence never makes." },
  { id: "t11rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The recipe relied on three imported ingredients ______ saffron, vanilla beans, and aged cheese.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["ingredients,", "ingredients:", "ingredients;", "ingredients"], correct: 1, explanation: "Punctuation rule: a colon follows a complete clause to introduce a list. \"The recipe relied on three imported ingredients\" is a complete clause, and \"saffron, vanilla beans, and aged cheese\" is the list naming them, so the colon (B) is correct. A comma (A) is too weak to formally introduce the list after a full clause. A semicolon (C) must join two independent clauses, but the list is not a clause. No punctuation (D) attaches the list with no signal at all." },
  { id: "t11rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The forecast nailed the hurricane's landfall location. ______, it badly underestimated how much rain the storm would dump inland.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "The forecast \"nailed the... landfall location\" (a success) but \"badly underestimated\" the rainfall (a failure); this reversal calls for the concessive transition \"Nonetheless\" (B), which is correct. \"Indeed\" (A) reinforces a prior point, but the rain failure does not echo the landfall success. \"Therefore\" (C) signals a result, yet the underestimate is not caused by the accurate landfall call. \"Likewise\" (D) signals similarity, but the two outcomes differ." },
  { id: "t11rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, students who used the new study app scored 15% higher on recall tests but reported spending 25% more time studying than the control group.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The app improved recall scores but required more study time.", "The app improved scores while saving time.", "The app had no measurable effect.", "The control group scored higher on recall."], correct: 0, explanation: "The data show app users \"scored 15% higher\" (benefit) but \"spent 25% more time studying\" (cost), so choice A — improved recall but more time — is supported. Choice B (\"improved scores while saving time\") contradicts the 25% MORE time. Choice C (\"no measurable effect\") ignores the 15% score gain. Choice D (\"control group scored higher\") reverses the result; the app users scored higher." },
  { id: "t11rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The sculpture that stands in the courtyard between the two libraries ______ from the artist's final decade.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["date", "dates", "dating", "to date"], correct: 1, explanation: "Subject-verb agreement rule: the verb agrees with the true subject, not with a noun in an intervening modifier. The subject is the singular \"sculpture\"; \"that stands... between the two libraries\" is a modifier, and \"libraries\" is not the subject. The singular verb \"dates\" (B) is correct. \"Date\" (A) is the plural form, wrongly agreeing with \"libraries.\" \"Dating\" (C) is a participle and \"to date\" (D) is an infinitive; neither can serve as the sentence's main verb, leaving it without a complete predicate." },
  { id: "t11rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor's reputation for ______ — for trimming every sentence to its leanest possible form — made writers both dread and admire her.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["austerity", "extravagance", "indecision", "vagueness"], correct: 0, explanation: "The dashes define the blank: a reputation \"for trimming every sentence to its leanest possible form.\" Severe spareness is \"austerity\" (A), so it is correct. \"Extravagance\" (B) means excess and lavishness, the opposite of trimming to lean form. \"Indecision\" (C) means inability to decide, but ruthless trimming shows firm decisiveness. \"Vagueness\" (D) means lack of precision, yet trimming to the leanest form is exact, not vague." },
  { id: "t11rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The historian begins by granting that early telescopes were blurry and small, then argues that these very flaws drove the lens-grinding advances that produced today's giant observatories.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It turns an early weakness into the source of later strengths.", "It denies that early telescopes had any flaws.", "It claims telescopes never improved.", "It lists telescope prices over time."], correct: 0, explanation: "The historian grants that early telescopes were \"blurry and small\" but argues \"these very flaws drove the lens-grinding advances\" behind today's observatories — turning an early weakness into the source of later strengths, so choice A is correct. Choice B (\"denies that early telescopes had any flaws\") contradicts the granted \"blurry and small.\" Choice C (\"telescopes never improved\") contradicts the \"advances\" that produced giant observatories. Choice D (\"lists telescope prices over time\") invents content the text never mentions." },
  { id: "t11rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having studied the score for weeks ______ the conductor led the orchestra entirely from memory.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the orchestra was led from memory", "the conductor led the orchestra entirely from memory", "from memory the orchestra was conducted", "it was led from memory, the orchestra"], correct: 1, explanation: "Modifier rule: the introductory phrase \"Having studied the score for weeks\" must be followed by the noun that did the studying. Only a person can study a score, so \"the conductor\" must come first; choice B does this and is correct. Choice A makes \"the orchestra\" the one that studied the score — a dangling modifier. Choice C (\"from memory the orchestra was conducted\") again leaves \"the orchestra\" as the illogical studier. Choice D (\"it was led from memory, the orchestra\") makes the pronoun \"it\" the subject of the modifier, which also cannot have studied the score and is awkwardly inverted." },
  { id: "t11rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine produced strong immunity in laboratory mice. ______, its effect in human volunteers proved far weaker, and a larger trial is now planned.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In humans, however", "For this reason", "Similarly"], correct: 1, explanation: "The vaccine gave \"strong immunity\" in mice but a \"far weaker\" effect in humans; this contrast is best marked by \"In humans, however\" (B), whose \"however\" signals the reversal and whose phrase names the new subject. \"Consequently\" (A) and \"For this reason\" (C) signal a result, but the weak human effect is not caused by the strong mouse result. \"Similarly\" (D) signals likeness, yet the two outcomes are opposite, not alike." },
  { id: "t11rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, in which a four-note motif introduced in the opening bars returns, disguised, in every movement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "fragmented", "random", "aimless"], correct: 0, explanation: "The relative clause explains the blank: a four-note motif from the opening \"returns, disguised, in every movement,\" tying the whole symphony together. A design unified this way is \"cohesive\" (A), so it is correct, and the critic admired it. \"Fragmented\" (B) means broken into disconnected pieces, the opposite of a recurring unifying motif. \"Random\" (C) and \"aimless\" (D) imply no pattern, contradicting a motif that deliberately recurs throughout." },
  { id: "t11rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across five schools, classes that added a daily reading block saw test scores rise by an average of 12%, while classes that kept their usual schedule saw no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding a daily reading block was associated with higher test scores.", "Removing reading time raised scores.", "Reading time had no relationship to scores.", "All classes kept their usual schedule."], correct: 0, explanation: "The data show classes that \"added a daily reading block\" had scores rise 12% while classes keeping their usual schedule \"saw no change\"; this links the added reading to higher scores, so choice A is correct. Choice B (\"removing reading time raised scores\") reverses the change — reading was added, not removed. Choice C (\"no relationship to scores\") ignores the 12% gap between the groups. Choice D (\"all classes kept their usual schedule\") contradicts the classes that added a reading block." },
  { id: "t11rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The composer's early works — bold, restless, and a little raw ______ already hinted at the mature style critics would later celebrate.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["works —", "works,", "works", "works;"], correct: 0, explanation: "Punctuation rule: a parenthetical aside set off with a dash must be closed by a matching dash. The interrupting description \"— bold, restless, and a little raw\" opens with a dash, so it must close with a second dash after \"works,\" making \"works —\" (A) correct. A comma (B) cannot pair with an opening dash; mismatched marks are not allowed. No punctuation (C) leaves the aside unclosed and runs it into the main clause. A semicolon (D) also fails to match the dash and would wrongly imply two independent clauses." },
  { id: "t11rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Investors dismissed the forecast as ______, only to watch the predicted boom arrive within the year.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overblown", "prophetic", "accurate", "reliable"], correct: 0, explanation: "Investors \"dismissed\" the forecast, so the blank must be a negative judgment, and \"only to watch the predicted boom arrive\" shows that judgment was mistaken. To dismiss a forecast as \"overblown\" (A) — exaggerated — fits both the dismissal and the irony of being wrong, so A is correct. \"Prophetic\" (B), \"accurate\" (C), and \"reliable\" (D) are all praise; you do not dismiss a forecast by calling it accurate, so each contradicts \"dismissed.\"" },
  { id: "t11rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One archaeologist credits the settlement's collapse to a sudden climate shift; another blames a breakdown in trade. A third suggests that each weakness deepened the other.", prompt: "Which choice best describes the third archaeologist's position?", type: "mcq", choices: ["The two proposed causes worsened one another to bring about the collapse.", "Neither climate nor trade mattered at all.", "Only the climate shift was to blame.", "The settlement never actually collapsed."], correct: 0, explanation: "The third archaeologist suggests \"each weakness deepened the other,\" meaning the climate shift and the trade breakdown worsened one another to cause the collapse; choice A captures this combined view and is correct. Choice B (\"neither... mattered at all\") contradicts a position that treats both as contributing causes. Choice C (\"only the climate shift was to blame\") is the first archaeologist's single-cause view, not the third's. Choice D (\"never actually collapsed\") denies the collapse all three are explaining." },
  { id: "t11rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The pilots aborted the takeoff ______ a warning light had flashed on the instrument panel.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["takeoff, a", "takeoff; a", "takeoff the", "takeoff: a"], correct: 1, explanation: "Punctuation rule: a semicolon joins two independent clauses. \"The pilots aborted the takeoff\" and \"a warning light had flashed on the instrument panel\" are both complete clauses, so the semicolon (B) is correct. A comma alone (A) creates a comma splice. \"Takeoff the\" (C) fuses the clauses into a run-on with no punctuation. A colon (D) introduces an explanation or list after a complete clause; though the second clause does explain why, the SAT prefers the semicolon here because what follows is a full independent clause stating a separate fact rather than a defining elaboration — and only one of these four can be the keyed answer, with the colon option redundant to the semicolon's clause-joining role." },
  { id: "t11rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the reform's gains were unevenly distributed. ______, urban hospitals received new equipment while rural clinics got almost nothing.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The first sentence states a general point (the gains \"were unevenly distributed\"); the second gives a concrete example of it (urban hospitals got equipment, rural clinics got almost nothing). A transition introducing a specific case fits, so \"Specifically\" (A) is correct. \"In contrast\" (B) and \"Nevertheless\" (C) signal opposition, but the example agrees with and illustrates the claim rather than opposing it. \"Otherwise\" (D) means 'if not,' a consequence that does not fit an illustration." },
  { id: "t11rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying every thread together, the director leaves the film's ending ______, inviting viewers to imagine the characters' fates for themselves.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "settled", "predictable", "resolved"], correct: 0, explanation: "\"Rather than tying every thread together\" and \"inviting viewers to imagine the characters' fates for themselves\" show the ending is left open to interpretation, which is \"ambiguous\" (A), so A is correct. \"Settled\" (B) and \"resolved\" (D) mean fully tied up — the opposite of an ending the director deliberately leaves open. \"Predictable\" (C) means easy to foresee, but an open ending that viewers must imagine is the reverse of predictable." },
  { id: "t11rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her experiment ran for only a month, but she argues that the trend she observed was so steep and steady that it justifies a year-long follow-up.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She acknowledges a limitation while defending the result's importance.", "She claims her experiment was flawless.", "She abandons her finding entirely.", "She argues no further study is needed."], correct: 0, explanation: "The author \"concedes that her experiment ran for only a month\" (acknowledging a limitation) but \"argues that the trend... justifies a year-long follow-up\" (defending its importance); choice A captures this concede-then-defend reasoning and is correct. Choice B (\"claims her experiment was flawless\") ignores the conceded one-month limitation. Choice C (\"abandons her finding entirely\") contradicts her defense of the trend. Choice D (\"argues no further study is needed\") contradicts her explicit call for a year-long follow-up." },
];

// ─────────────────────── PRACTICE TEST 11 · MATH M1 (22) ─────────────────────
const T11_M_M1: SatQuestion[] = [
  { id: "t11m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve 5x + 8 = 43 for x. Subtract 8 from both sides: 5x = 43 − 8 = 35. Divide both sides by 5: x = 35 ÷ 5 = 7. Answer: 7. Check: 5(7) + 8 = 35 + 8 = 43, matching the equation. Trap: dividing 43 by 5 first (8.6) without removing the +8 reverses the order of operations." },
  { id: "t11m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 2 cups of sugar for every 16 cupcakes. How many cups are needed for 40 cupcakes?", type: "mcq", choices: ["5", "4", "6", "8"], correct: 0, explanation: "Goal: scale the ratio 2 cups : 16 cupcakes up to 40 cupcakes. Set up the proportion 2/16 = x/40. Cross-multiply: 16x = 2 × 40 = 80, so x = 80 ÷ 16 = 5 cups. Answer: 5 (choice A). Check via unit rate: 2 ÷ 16 = 0.125 cup per cupcake, and 0.125 × 40 = 5, matching. Trap: guessing 4 (B) by scaling the wrong way; choices 6 and 8 overshoot the proportion." },
  { id: "t11m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 4, what is the value of f(2)?", type: "mcq", choices: ["8", "2", "32", "20"], correct: 0, explanation: "Goal: evaluate f(2) for f(x) = 3x² − 4. Substitute x = 2: f(2) = 3(2²) − 4. By order of operations, square first: 2² = 4. Multiply: 3 × 4 = 12. Subtract: 12 − 4 = 8. Answer: 8 (choice A). Check: the squaring applies only to x, so 3(4) − 4 = 8 is consistent. Trap: 32 (C) comes from (3·2)² = 36 territory — squaring after multiplying instead of before; only x is squared, not 3x." },
  { id: "t11m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 9. What is its diameter?", type: "grid", gridAnswers: ["18"], explanation: "Goal: find the diameter of a circle with radius 9. The diameter equals twice the radius: d = 2r = 2 × 9 = 18. Answer: 18. Check: the radius is half the diameter, and 18 ÷ 2 = 9, the given radius. Trap: confusing diameter with circumference (2πr ≈ 56.5) and reaching for π; the diameter has no π in it." },
  { id: "t11m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 3x + 2 passes through the point (4, k). What is the value of k?", type: "grid", gridAnswers: ["14"], explanation: "Goal: find k, the y-value when the line y = 3x + 2 passes through (4, k). Substitute x = 4: k = 3(4) + 2. Multiply first: 3 × 4 = 12. Add: 12 + 2 = 14. Answer: 14. Check: the point (4, 14) lies on y = 3x + 2 since 3(4) + 2 = 14. Trap: 18 comes from adding before multiplying, 3(4 + 2); order of operations requires the multiplication 3 × 4 first." },
  { id: "t11m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: find x given that the mean of 6, 10, and x is 9. The mean is the sum over the count: (6 + 10 + x)/3 = 9. Multiply both sides by 3: 6 + 10 + x = 27, so 16 + x = 27. Subtract 16: x = 11. Answer: 11 (choice A). Check: (6 + 10 + 11)/3 = 27/3 = 9, the given mean. Trap: 9 (B) wrongly treats the sum as 9; the sum of three numbers averaging 9 must be 27, not 9." },
  { id: "t11m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 7 = 28, what is the value of x?", type: "mcq", choices: ["7", "21", "9", "35"], correct: 0, explanation: "Goal: solve 3x + 7 = 28 for x. Subtract 7 from both sides: 3x = 28 − 7 = 21. Divide both sides by 3: x = 21 ÷ 3 = 7. Answer: 7 (choice A). Check: 3(7) + 7 = 21 + 7 = 28, matching. Trap: 21 (B) is the value of 3x reported before the final division by 3." },
  { id: "t11m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the sum of the solutions to x² − 9x + 20 = 0. Factor: two numbers multiplying to 20 and summing to 9 are 4 and 5, so (x − 4)(x − 5) = 0. The roots are x = 4 and x = 5, and their sum is 4 + 5 = 9. Equivalently, for ax² + bx + c the sum of roots is −b/a = −(−9)/1 = 9. Answer: 9. Check: 4 × 5 = 20 matches the constant term. Trap: reporting the product, 20, instead of the sum, 9." },
  { id: "t11m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A price increased from $40 to $50. What was the percent increase?", type: "mcq", choices: ["25%", "20%", "10%", "125%"], correct: 0, explanation: "Goal: find the percent increase from $40 to $50. Percent increase = (change ÷ original) × 100. The change is 50 − 40 = 10. Divide by the original: 10 ÷ 40 = 0.25. Convert to percent: 0.25 × 100 = 25%. Answer: 25% (choice A). Check: 25% of 40 is 10, and 40 + 10 = 50, the new price. Trap: 20% (B) comes from dividing by the new price 50 instead of the original 40; percent change always uses the original as the base." },
  { id: "t11m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 65°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["70"], explanation: "Goal: find the third angle of a triangle with angles 45° and 65°. The interior angles of any triangle sum to 180°. Subtract the two known angles: 180 − 45 − 65 = 70°. Answer: 70. Check: 45 + 65 + 70 = 180, the required total. Trap: 110 comes from summing only the two given angles (45 + 65) and stopping; that sum must be subtracted from 180 to find the third angle." },
  { id: "t11m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $25 per hour. Which equation gives the cost C for h hours?", type: "mcq", choices: ["C = 25h + 40", "C = 40h + 25", "C = 65h", "C = 25h − 40"], correct: 0, explanation: "Goal: write the cost C for h hours given a $40 flat fee plus $25 per hour. The per-hour rate multiplies the variable h (25h), and the one-time fee is the constant (+40), giving C = 25h + 40. Answer: C = 25h + 40 (choice A). Check: for h = 2 hours, C = 25(2) + 40 = 50 + 40 = $90, which equals two hours of labor plus the fee. Trap: 40h + 25 (B) swaps fee and rate, wrongly charging $40 every hour; 65h (C) merges them into one rate, losing the fixed fee." },
  { id: "t11m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 3) = x² + bx − 15, what is the value of b?", type: "grid", gridAnswers: ["2"], explanation: "Goal: find b where (x + 5)(x − 3) = x² + bx − 15. Expand the left side with FOIL: x·x = x², x·(−3) = −3x, 5·x = 5x, 5·(−3) = −15, giving x² − 3x + 5x − 15. Combine the middle terms: −3x + 5x = 2x, so the product is x² + 2x − 15. Match to x² + bx − 15: b = 2. Answer: 2. Check: the constant −15 matches and the middle coefficient is 2. Trap: 8 comes from adding 5 and 3; the middle term combines −3 and +5, which is +2, not 8." },
  { id: "t11m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 300 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["120", "40", "75", "180"], correct: 0, explanation: "Goal: find how many of 300 people preferred coffee when 40% did. Convert the percent to a decimal and multiply: 0.40 × 300 = 120. Answer: 120 (choice A). Check: 120 out of 300 is 120/300 = 0.40 = 40%, matching. Trap: 180 (D) is the number who did NOT prefer coffee (60% × 300); the question asks for the 40% who did." },
  { id: "t11m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 3) = 2x + 6, what is the value of x?", type: "mcq", choices: ["7", "3", "9", "5"], correct: 0, explanation: "Goal: solve 5(x − 3) = 2x + 6 for x. Distribute the 5: 5x − 15 = 2x + 6. Subtract 2x from both sides: 3x − 15 = 6. Add 15: 3x = 21. Divide by 3: x = 7. Answer: 7 (choice A). Check: 5(7 − 3) = 5(4) = 20 and 2(7) + 6 = 14 + 6 = 20, both sides equal. Trap: forgetting to distribute the 5 to the −3 (writing 5x − 3) throws off every later step." },
  { id: "t11m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter of a rectangle with length 12 and width 5. Perimeter is twice the sum of length and width: P = 2(l + w) = 2(12 + 5) = 2(17) = 34. Answer: 34 (choice A). Check: adding all four sides, 12 + 5 + 12 + 5 = 34, the same. Trap: 60 (B) is the area (length × width = 12 × 5), not the perimeter; 17 (C) is just l + w without doubling." },
  { id: "t11m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve 3^(x−1) = 27 for x. Rewrite 27 as a power of 3: 27 = 3³. So 3^(x−1) = 3³, and with equal bases the exponents must match: x − 1 = 3. Add 1: x = 4. Answer: 4. Check: 3^(4−1) = 3³ = 27, matching. Trap: answering 3 by solving 3^x = 27 and ignoring the −1 in the exponent; the exponent is x − 1, so x = 3 + 1 = 4." },
  { id: "t11m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "100", "180"], correct: 0, explanation: "Goal: convert 5 inches on a map to real miles at a scale of 1 inch = 30 miles. Multiply the map distance by the scale: 5 inches × 30 miles per inch = 150 miles. Answer: 150 (choice A). Check: 150 miles ÷ 30 miles per inch = 5 inches, the map distance. Trap: dividing instead of multiplying (5 ÷ 30 ≈ 0.17) gives an unrealistically small distance; each inch stands for 30 miles, so inches are multiplied." },
  { id: "t11m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope of the line through (2, 3) and (6, 15). Slope = (change in y) ÷ (change in x) = (y₂ − y₁)/(x₂ − x₁). Substitute: (15 − 3)/(6 − 2) = 12/4 = 3. Answer: 3. Check: rising 12 over a run of 4 is the same ratio as rising 3 over a run of 1. Trap: 1/3 comes from inverting the formula, (6 − 2)/(15 − 3); the change in y goes on top, the change in x on the bottom." },
  { id: "t11m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x + 5, what value of x makes f(x) = 25?", type: "mcq", choices: ["5", "7", "6", "4"], correct: 0, explanation: "Goal: find x where f(x) = 25 for f(x) = 4x + 5. Set 4x + 5 = 25. Subtract 5 from both sides: 4x = 20. Divide by 4: x = 5. Answer: 5 (choice A). Check: f(5) = 4(5) + 5 = 20 + 5 = 25, matching. Trap: dividing 25 by 4 (6.25) before removing the +5 skips clearing the constant; subtract 5 first, then divide." },
  { id: "t11m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 7. What is its area, in terms of π?", type: "mcq", choices: ["49π", "14π", "7π", "21π"], correct: 0, explanation: "Goal: find the area of a circle with radius 7, in terms of π. Area = πr². Substitute r = 7: A = π(7²) = π(49) = 49π. Answer: 49π (choice A). Check: 7² = 49, so the area is 49π square units. Trap: 14π (B) is the circumference (2πr = 2π·7), not the area; area uses r², not 2r." },
  { id: "t11m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x − y = 17 and y = 3, what is the value of x?", type: "mcq", choices: ["4", "3", "5", "7"], correct: 0, explanation: "Goal: find x given 5x − y = 17 and y = 3. Substitute y = 3: 5x − 3 = 17. Add 3 to both sides: 5x = 20. Divide by 5: x = 4. Answer: 4 (choice A). Check: 5(4) − 3 = 20 − 3 = 17, matching. Trap: forgetting to add 3 back and dividing 17 by 5 (3.4) skips clearing the −3; isolate 5x first, then divide." },
  { id: "t11m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 30-hour week?", type: "grid", gridAnswers: ["660"], explanation: "Goal: find total pay for 30 hours at $22 per hour. Multiply the hourly rate by the hours: 22 × 30 = 660 dollars. Answer: 660. Check: 22 × 30 = 22 × 3 × 10 = 66 × 10 = 660, and 660 ÷ 30 = 22 per hour, matching the rate. Trap: misplacing a zero to answer 66 (forgetting the ×10) or 6,600 (an extra zero)." },
];

// ─────────────────────── PRACTICE TEST 11 · MATH M2 easy (22) ────────────────
const T11_M_M2E: SatQuestion[] = [
  { id: "t11m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 6 = 14, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for x. The equation is x + 6 = 14. Subtract 6 from both sides to isolate x: x + 6 − 6 = 14 − 6, so x = 8. Check: 8 + 6 = 14, which matches the equation, so x = 8 is correct. Trap: adding 6 instead of subtracting gives 14 + 6 = 20; the +6 must be undone by subtraction, not reinforced by addition." },
  { id: "t11m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 20% of 60?", type: "mcq", choices: ["12", "20", "30", "120"], correct: 0, explanation: "Goal: find 20% of 60. \"Percent of\" means convert the percent to a decimal and multiply: 20% = 0.20, so 0.20 × 60 = 12. Answer: 12 (choice A). Check: 10% of 60 is 6, and 20% is double that, 12, which agrees. Trap: 30 (C) comes from halving 60 as if 20% meant 50%. 20 (B) just echoes the number 20, and 120 (D) comes from multiplying by 2 instead of 0.2." },
  { id: "t11m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 9 and a width of 4. What is its area?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the area of the rectangle. Area of a rectangle = length × width. Substitute: A = 9 × 4 = 36 square units. Answer: 36. Check: a 9-by-4 grid contains 9 columns of 4 unit squares, 9 × 4 = 36 squares, confirming the area. Trap: using the perimeter formula 2(length + width) = 2(9 + 4) = 2(13) = 26 answers a different question; area multiplies the sides, it does not add them." },
  { id: "t11m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 7x = 56, what is the value of x?", type: "mcq", choices: ["8", "7", "49", "63"], correct: 0, explanation: "Goal: solve 7x = 56 for x. Since x is multiplied by 7, undo that by dividing both sides by 7: 7x ÷ 7 = 56 ÷ 7, so x = 8. Answer: 8 (choice A). Check: 7 × 8 = 56, which matches. Trap: 49 (C) comes from subtracting (56 − 7 = 49) instead of dividing; multiplication is undone by division, not subtraction. 63 (D) comes from adding 7, and 7 (B) just repeats the coefficient." },
  { id: "t11m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: evaluate 5² − 4. By order of operations (PEMDAS), exponents come before subtraction. First the exponent: 5² = 5 × 5 = 25. Then subtract: 25 − 4 = 21. Answer: 21. Check: working backward, 21 + 4 = 25 = 5², confirming the value. Trap: subtracting before squaring gives (5 − 4)² = 1² = 1, which violates order of operations; the exponent applies only to the 5, not to (5 − 4)." },
  { id: "t11m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 8 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["2/3", "8/12", "3/4", "1/8"], correct: 0, explanation: "Goal: express the share of games won as a fraction. Wins over total games = 8/12. Simplify by dividing numerator and denominator by their greatest common factor, 4: 8 ÷ 4 = 2 and 12 ÷ 4 = 3, giving 2/3. Answer: 2/3 (choice A). Check: 2/3 = 0.667 and 8/12 = 0.667, the same value, so the reduction is correct. Trap: 8/12 (B) is the right ratio but not fully reduced; when a simplified equivalent is offered, choose it. 3/4 (C) is too large, and 1/8 (D) misreads the numbers." },
  { id: "t11m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 5 = 11, what is the value of x?", type: "grid", gridAnswers: ["16"], explanation: "Goal: solve x − 5 = 11 for x. Undo the subtraction of 5 by adding 5 to both sides: x − 5 + 5 = 11 + 5, so x = 16. Answer: 16. Check: 16 − 5 = 11, which matches the original equation. Trap: subtracting 5 (11 − 5 = 6) reinforces the operation instead of undoing it; a −5 must be cancelled with +5." },
  { id: "t11m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 18, and 24?", type: "mcq", choices: ["18", "24", "16", "54"], correct: 0, explanation: "Goal: find the mean of the three values. Average = (sum of values) ÷ (number of values). Add: 12 + 18 + 24 = 54. There are 3 values, so divide: 54 ÷ 3 = 18. Answer: 18 (choice A). Check: 18 is the middle value of evenly spaced numbers 12, 18, 24, which equals their average, confirming the result. Trap: 54 (D) is the sum, not the average; you must still divide by 3. 24 (B) is just the largest value, and 16 (C) is an arithmetic slip." },
  { id: "t11m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 6. What is its perimeter?", type: "grid", gridAnswers: ["24"], explanation: "Goal: find the perimeter of the square. Perimeter is the total distance around, and a square has 4 equal sides, so P = 4 × side. Substitute: P = 4 × 6 = 24 units. Answer: 24. Check: adding the four sides 6 + 6 + 6 + 6 = 24 gives the same result. Trap: 6 × 6 = 36 is the area (side squared), not the perimeter; perimeter sums the sides while area multiplies two of them." },
  { id: "t11m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 3 = 15, what is the value of x?", type: "mcq", choices: ["6", "9", "12", "5"], correct: 0, explanation: "Goal: solve 2x + 3 = 15 for x. First undo the +3 by subtracting 3 from both sides: 2x + 3 − 3 = 15 − 3, so 2x = 12. Then undo the ×2 by dividing both sides by 2: x = 12 ÷ 2 = 6. Answer: 6 (choice A). Check: 2(6) + 3 = 12 + 3 = 15, which matches. Trap: 12 (C) is the value of 2x before the final division by 2; you must still divide. 9 (B) comes from subtracting 6, and 5 (D) is an arithmetic slip." },
  { id: "t11m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 8, what is f(6)?", type: "grid", gridAnswers: ["14"], explanation: "Goal: evaluate the function at x = 6. The rule f(x) = x + 8 says \"add 8 to the input.\" Substitute 6 for x: f(6) = 6 + 8 = 14. Answer: 14. Check: the function adds 8, and 6 + 8 = 14, consistent with the rule. Trap: multiplying gives 6 × 8 = 48; the function specifies addition, so the input is added to 8, not multiplied by it." },
  { id: "t11m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 pencils for $3. How much do 10 pencils cost?", type: "mcq", choices: ["$6", "$5", "$8", "$3"], correct: 0, explanation: "Goal: find the cost of 10 pencils given 5 pencils cost $3. Set up a proportion: 5 pencils / $3 = 10 pencils / c. Since 10 is 2 × 5, the cost is also 2 ×: c = 2 × $3 = $6. Answer: $6 (choice A). Check: at $3 per 5 pencils, the rate is $0.60 per pencil, and 10 × $0.60 = $6, confirming the result. Trap: $8 (C) comes from adding $3 + $5, mixing the count 5 with a dollar amount; the price scales with the quantity, it is not added to it. $5 (B) and $3 (D) ignore the doubling." },
  { id: "t11m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 48, what is the value of x?", type: "mcq", choices: ["8", "6", "42", "54"], correct: 0, explanation: "Goal: solve 6x = 48 for x. Since x is multiplied by 6, divide both sides by 6: 6x ÷ 6 = 48 ÷ 6, so x = 8. Answer: 8 (choice A). Check: 6 × 8 = 48, which matches. Trap: 42 (C) comes from subtracting (48 − 6 = 42) instead of dividing; a multiplication is undone by division. 54 (D) comes from adding 6, and 6 (B) just repeats the coefficient." },
  { id: "t11m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 8 and a height of 5. What is its area?", type: "grid", gridAnswers: ["20"], explanation: "Goal: find the area of the triangle. Area of a triangle = (1/2) × base × height. Substitute base = 8 and height = 5: A = (1/2)(8)(5). Multiply step by step: 8 × 5 = 40, then 40 × (1/2) = 20 square units. Answer: 20. Check: a triangle is half of a rectangle 8 by 5 (area 40), so half is 20, consistent. Trap: 40 forgets the (1/2) factor, which gives the full rectangle's area rather than the triangle's." },
  { id: "t11m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 80?", type: "mcq", choices: ["20", "25", "40", "16"], correct: 0, explanation: "Goal: find 25% of 80. Convert the percent to a decimal and multiply: 25% = 0.25, so 0.25 × 80 = 20. Equivalently, 25% = 1/4, and 80 ÷ 4 = 20. Answer: 20 (choice A). Check: four 20s make 80 (20 × 4 = 80), so 20 is exactly one-quarter, confirming the result. Trap: 40 (C) is 50% of 80, which comes from confusing 25% with half. 25 (B) just echoes the percent, and 16 (D) uses the wrong fraction." },
  { id: "t11m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "grid", gridAnswers: ["21"], explanation: "Goal: solve x/3 = 7 for x. Since x is divided by 3, undo that by multiplying both sides by 3: (x/3) × 3 = 7 × 3, so x = 21. Answer: 21. Check: 21 ÷ 3 = 7, which matches the equation. Trap: dividing 7 ÷ 3 ≈ 2.33 repeats the division instead of reversing it; a division by 3 must be undone by multiplication by 3." },
  { id: "t11m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "6", "12"], correct: 0, explanation: "Goal: evaluate 3³. The exponent 3 means use 3 as a factor three times: 3³ = 3 × 3 × 3. Compute stepwise: 3 × 3 = 9, then 9 × 3 = 27. Answer: 27 (choice A). Check: 3³ should exceed 3² = 9, and 27 > 9 as expected. Trap: 9 (B) is 3² (only two factors), stopping one multiplication short. 6 (C) comes from 3 × 2 (treating the exponent as a multiplier), and 12 from 3 × 4." },
  { id: "t11m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 90 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["30", "90", "270", "45"], correct: 0, explanation: "Goal: find the average speed. Average speed = distance ÷ time. Substitute: 90 miles ÷ 3 hours = 30 miles per hour. Answer: 30 (choice A). Check: at 30 mph for 3 hours, distance = 30 × 3 = 90 miles, matching the given distance. Trap: 270 (C) comes from multiplying 90 × 3 instead of dividing; speed is a rate (distance per hour), so you divide. 90 (B) ignores the time, and 45 halves the distance instead." },
  { id: "t11m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 8 = 12, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve 4x − 8 = 12 for x. First undo the −8 by adding 8 to both sides: 4x − 8 + 8 = 12 + 8, so 4x = 20. Then divide both sides by 4: x = 20 ÷ 4 = 5. Answer: 5. Check: 4(5) − 8 = 20 − 8 = 12, which matches. Trap: dividing 12 ÷ 4 = 3 before adding the 8 back skips a step; the constant term must be cleared before dividing by the coefficient." },
  { id: "t11m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a diameter of 18. What is its radius?", type: "mcq", choices: ["9", "18", "36", "6"], correct: 0, explanation: "Goal: find the radius from the diameter. The diameter is twice the radius (d = 2r), so the radius is half the diameter: r = d ÷ 2 = 18 ÷ 2 = 9. Answer: 9 (choice A). Check: doubling the radius gives 2 × 9 = 18, the stated diameter, confirming the result. Trap: 36 (C) doubles the diameter instead of halving it, reversing the relationship. 18 (B) just repeats the diameter, and 6 uses the wrong divisor." },
  { id: "t11m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "2", "5"], correct: 0, explanation: "Goal: find y. Substitute the given x = 5 into y = 3x: y = 3 × 5 = 15. Answer: 15 (choice A). Check: 3x with x = 5 means three groups of 5, which is 15, consistent. Trap: 8 (B) comes from adding 3 + 5; \"3x\" means 3 times x, so the operation is multiplication, not addition. 5 (D) ignores the factor 3, and 2 comes from subtracting." },
  { id: "t11m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A jar holds 9 green and 6 yellow marbles. What fraction of the marbles are green?", type: "mcq", choices: ["3/5", "9/6", "2/5", "1/2"], correct: 0, explanation: "Goal: find the fraction of marbles that are green. Fraction = green ÷ total. Total marbles = 9 + 6 = 15, so the fraction is 9/15. Simplify by dividing top and bottom by 3: 9 ÷ 3 = 3 and 15 ÷ 3 = 5, giving 3/5. Answer: 3/5 (choice A). Check: 3/5 = 0.6 and 9/15 = 0.6, the same value. Trap: 9/6 (B) puts green over yellow instead of green over the total, forgetting that the denominator must be all 15 marbles. 2/5 and 1/2 use wrong totals." },
];

// ─────────────────────── PRACTICE TEST 11 · MATH M2 hard (22) ────────────────
const T11_M_M2H: SatQuestion[] = [
  { id: "t11m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve x² − 64 = 0 for the positive x. Add 64 to both sides: x² = 64. Take the square root of both sides: x = ±√64 = ±8, so x = 8 or x = −8. The condition x > 0 selects the positive root, x = 8. Answer: 8. Check: 8² − 64 = 64 − 64 = 0, and 8 > 0, satisfying both conditions. Trap: −8 also makes x² = 64 but is excluded by x > 0; ignoring the restriction picks the wrong root." },
  { id: "t11m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x + 2y = 24 and x − 2y = 0, what is the value of x?", type: "mcq", choices: ["4", "8", "6", "3"], correct: 0, explanation: "Goal: find x from the system. The y-terms are +2y and −2y, which are opposites, so add the equations to eliminate y: (5x + 2y) + (x − 2y) = 24 + 0. Combine: 5x + x = 6x and 2y − 2y = 0, giving 6x = 24. Divide by 6: x = 4. Answer: 4 (choice A). Check: x − 2y = 0 gives y = x/2 = 2, then 5(4) + 2(2) = 20 + 4 = 24, matching the first equation. Trap: subtracting the equations instead of adding leaves 4x + 4y = 24, which does not isolate x; you must add to cancel the opposite y-terms." },
  { id: "t11m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve 2^x = 64. Rewrite 64 as a power of 2 by repeated doubling: 2, 4, 8, 16, 32, 64, which is 2⁶. So 2^x = 2⁶. With equal bases, the exponents must be equal: x = 6. Answer: 6. Check: 2⁶ = 64, which matches. Trap: dividing 64 ÷ 2 = 32 treats the exponent as ordinary division; an exponential equation is solved by matching powers of the base, not by dividing." },
  { id: "t11m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $90 is marked up by 20%. What is the new price?", type: "mcq", choices: ["$108", "$110", "$72", "$112"], correct: 0, explanation: "Goal: find the price after a 20% markup. A markup adds a percent of the original to the original. Find 20% of 90: 0.20 × 90 = 18. Add it to the original: 90 + 18 = $108. (Equivalently, multiply by 1.20: 90 × 1.20 = 108.) Answer: $108 (choice A). Check: $18 is 20% of $90, and 108 − 90 = 18, the correct increase. Trap: $72 (C) comes from subtracting the $18, treating the markup as a discount; a markup raises the price. $110 and $112 are arithmetic slips." },
  { id: "t11m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 8 and 15. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find the hypotenuse of a right triangle with legs 8 and 15. Use the Pythagorean theorem a² + b² = c². Substitute the legs: 8² + 15² = c², so 64 + 225 = c², giving c² = 289. Take the square root: c = √289 = 17. Answer: 17. Check: 17² = 289 and 64 + 225 = 289, so the equation holds (this is the 8-15-17 Pythagorean triple). Trap: 23 comes from adding the legs 8 + 15 directly; the theorem requires squaring the legs, summing, then taking the root, not adding the lengths." },
  { id: "t11m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(4))?", type: "mcq", choices: ["28", "10", "30", "12"], correct: 0, explanation: "Goal: evaluate the composition p(p(4)) for p(x) = 3x − 2. Work from the inside out. Inner: p(4) = 3(4) − 2 = 12 − 2 = 10. Outer: apply p to that result, p(10) = 3(10) − 2 = 30 − 2 = 28. Answer: 28 (choice A). Check: each application multiplies by 3 and subtracts 2; 4 → 10 → 28 follows that rule. Trap: 10 (B) is only the inner value p(4); the function must be applied a second time." },
  { id: "t11m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 2y = 20 and x = y + 2, what is the value of y?", type: "grid", gridAnswers: ["2.8", "14/5"], explanation: "Goal: solve the system for y, given 3x + 2y = 20 and x = y + 2. Substitute x = y + 2 into the first equation: 3(y + 2) + 2y = 20. Distribute the 3: 3y + 6 + 2y = 20. Combine like terms: 5y + 6 = 20. Subtract 6: 5y = 14. Divide by 5: y = 14/5 = 2.8. Answer: 2.8 (or 14/5). Check: x = 2.8 + 2 = 4.8, and 3(4.8) + 2(2.8) = 14.4 + 5.6 = 20, matching. Trap: dropping the distribution and writing 3y + 2 + 2y gives the wrong middle step; the 3 multiplies both y and 2." },
  { id: "t11m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 7 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the x-coordinate h of the vertex of y = x² − 8x + 7. For y = ax² + bx + c the vertex is at h = −b/(2a). Identify a = 1 and b = −8. Substitute: h = −(−8)/(2 × 1) = 8/2 = 4. Answer: 4. Check: completing the square, x² − 8x + 7 = (x − 4)² − 9, so the vertex is at x = 4, confirming h = 4. Trap: −4 comes from forgetting the leading negative on −b, computing −8/2; the formula negates b, and −(−8) = +8." },
  { id: "t11m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 8/17. What is sin θ?", type: "mcq", choices: ["15/17", "8/15", "17/15", "15/8"], correct: 0, explanation: "Goal: find sin θ given cos θ = 8/17 in a right triangle. Cosine is adjacent/hypotenuse, so the adjacent leg is 8 and the hypotenuse 17. Find the opposite leg with the Pythagorean theorem: opposite = √(17² − 8²) = √(289 − 64) = √225 = 15. Then sin θ = opposite/hypotenuse = 15/17. Answer: 15/17 (choice A). Check: (8/17)² + (15/17)² = (64 + 225)/289 = 289/289 = 1, satisfying sin²θ + cos²θ = 1. Trap: 15/8 (D) is opposite/adjacent, which is tan θ, not sin θ." },
  { id: "t11m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find b > 0 so that x² + bx + 25 is a perfect square. A perfect-square trinomial has the form (x + a)² = x² + 2ax + a². Match the constant term: a² = 25, so a = 5 (taking the positive value). Match the middle term: b = 2a = 2 × 5 = 10. Answer: 10. Check: (x + 5)² = x² + 10x + 25, which matches with b = 10. Trap: 5 stops at a without doubling it; the middle coefficient is 2a, not a." },
  { id: "t11m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−1", "5", "8"], correct: 0, explanation: "Goal: find the y-intercept b of a line with slope −3 through (2, 5). Use y = mx + b. Substitute m = −3, x = 2, y = 5: 5 = −3(2) + b. Compute: 5 = −6 + b. Add 6 to both sides: b = 11. Answer: 11 (choice A). Check: the line y = −3x + 11 at x = 2 gives −6 + 11 = 5, matching the point. Trap: −1 (B) comes from a sign error, treating −3(2) as +6 so that 5 = 6 + b gives b = −1; the product of −3 and 2 is −6." },
  { id: "t11m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a phone costs $300. What was the original price?", type: "mcq", choices: ["$400", "$375", "$360", "$320"], correct: 0, explanation: "Goal: find the original price when $300 is the price after a 25% discount. A 25% discount means the customer pays 100% − 25% = 75% of the original, so 300 = 0.75 × original. Divide both sides by 0.75: original = 300 ÷ 0.75 = 400. Answer: $400 (choice A). Check: 25% of 400 is 100, and 400 − 100 = 300, the discounted price. Trap: $375 (B) comes from adding 25% of 300 ($75) to 300; the percent must be taken of the unknown original, not of the discounted price." },
  { id: "t11m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 81 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-9"], explanation: "Goal: find a < 0 with f(a) = 81 for f(x) = x². Set a² = 81 and take the square root: a = ±√81 = ±9, so a = 9 or a = −9. The condition a < 0 selects a = −9. Answer: −9. Check: (−9)² = 81 and −9 < 0, satisfying both. Trap: 9 also squares to 81 but is positive, so it is excluded by a < 0; ignoring the restriction picks the wrong root." },
  { id: "t11m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 5. What is its volume, in terms of π?", type: "mcq", choices: ["80π", "40π", "20π", "100π"], correct: 0, explanation: "Goal: find the volume of a cylinder with radius 4 and height 5. Volume of a cylinder = πr²h. Substitute r = 4, h = 5: V = π(4²)(5) = π(16)(5) = 80π. Answer: 80π (choice A). Check: r² = 16 and 16 × 5 = 80, so V = 80π is consistent. Trap: 20π (C) uses r instead of r² (π × 4 × 5); the radius must be squared in the volume formula." },
  { id: "t11m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["1.333...", "4/3"], explanation: "Goal: solve 1/x + 1/4 = 1 for x. Subtract 1/4 from both sides: 1/x = 1 − 1/4 = 3/4. Take the reciprocal of both sides: x = 4/3 ≈ 1.333. Answer: 4/3 (or 1.333…). Check: 1/(4/3) + 1/4 = 3/4 + 1/4 = 1, matching. Trap: 3/4 forgets the final reciprocal step; 1/x = 3/4 means x is the flip of 3/4, namely 4/3." },
  { id: "t11m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "3"], correct: 0, explanation: "Goal: find the product of the solutions to x² − 7x + 10 = 0. Factor: find two numbers multiplying to 10 and summing to −7, which are −2 and −5, so (x − 2)(x − 5) = 0. The roots are x = 2 and x = 5, and their product is 2 × 5 = 10. Equivalently, for ax² + bx + c, the product of roots is c/a = 10/1 = 10. Answer: 10 (choice A). Check: 2 × 5 = 10 and 2 + 5 = 7 (matching −b/a). Trap: 7 (B) is the sum of the roots, not the product." },
  { id: "t11m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of red to blue tiles in a box is 2:7. If there are 45 tiles total, how many are blue?", type: "mcq", choices: ["35", "10", "14", "30"], correct: 0, explanation: "Goal: find the number of blue tiles given a red:blue ratio of 2:7 and 45 tiles total. The ratio has 2 + 7 = 9 equal parts. Each part is 45 ÷ 9 = 5 tiles. Blue is 7 parts: 7 × 5 = 35. Answer: 35 (choice A). Check: red = 2 × 5 = 10, and 10 + 35 = 45, the total. Trap: 10 (B) is the red count, found by using 2 parts instead of blue's 7 parts." },
  { id: "t11m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 3, what is the area of the larger?", type: "grid", gridAnswers: ["48"], explanation: "Goal: find the larger triangle's area given a 1:4 linear scale factor and a smaller area of 3. For similar figures, area scales by the square of the linear ratio: (4)² = 16. Multiply the smaller area: 3 × 16 = 48. Answer: 48. Check: if linear sides quadruple, area grows 4 × 4 = 16 times, so 3 × 16 = 48 is consistent. Trap: 12 multiplies by 4 (the linear factor) instead of 16; areas scale by the square of the ratio, not the ratio itself." },
  { id: "t11m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: solve √(x + 5) = 6 for x. Remove the radical by squaring both sides: (√(x + 5))² = 6², so x + 5 = 36. Subtract 5: x = 31. Answer: 31. Check: √(31 + 5) = √36 = 6, matching the equation. Trap: 1 comes from computing 6 − 5 without first squaring the 6; the radical is cleared by squaring, which makes the right side 36, not 6." },
  { id: "t11m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 4y = 22 and y = 2, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "8"], correct: 0, explanation: "Goal: find x given 5x − 4y = 22 and y = 2. Substitute y = 2: 5x − 4(2) = 22, so 5x − 8 = 22. Add 8 to both sides: 5x = 30. Divide by 5: x = 6. Answer: 6 (choice A). Check: 5(6) − 4(2) = 30 − 8 = 22, matching. Trap: forgetting to add the 8 back and computing 22 ÷ 5 skips clearing the constant; the −8 must be removed before dividing by the coefficient 5." },
  { id: "t11m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find x where g(x) = 0 for g(x) = x² − 6x + 9. Factor: two numbers multiplying to 9 and summing to −6 are both −3, so g(x) = (x − 3)². Setting (x − 3)² = 0 requires x − 3 = 0, so x = 3. Answer: 3. Check: 3² − 6(3) + 9 = 9 − 18 + 9 = 0, matching. Trap: expecting two distinct roots; this is a perfect square with a single repeated root at x = 3." },
  { id: "t11m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of bacteria triples every hour. If it starts at 20, how many are there after 3 hours?", type: "mcq", choices: ["540", "180", "60", "1620"], correct: 0, explanation: "Goal: find the bacteria count after 3 hours of tripling, starting at 20. Tripling each hour multiplies by 3 per hour, so after 3 hours the factor is 3³ = 27. Compute: 20 × 27 = 540. (Step by step: 20 → 60 → 180 → 540.) Answer: 540 (choice A). Check: 60 after 1 hr, 180 after 2 hr, 540 after 3 hr, each three times the last. Trap: 60 (C) tripled only once, and 180 (B) tripled only twice (×9); three hours requires cubing the growth factor." },
];

